//
// The 1AM wallet, as its developer guide (https://1am.xyz/developers) describes it.
//
// What makes it the right wallet for this job is the thing it does *after* the signature: the
// transaction goes to ProofStation, which proves it and then balances it with DUST out of 1AM's
// own funded pool. The signer therefore needs no DUST, which is the only reason a mainnet
// deployment is possible here at all — DUST is generated by registered NIGHT, most NIGHT is
// cNIGHT on Cardano, and we have no route to Cardano. See docs/MAINNET.md, "DUST, which is the
// slow one".
//
// Two consequences run through this file. The wallet pays the fee, so the adapter is built with
// `payFees: true` and is *not* wrapped in `sponsoredWalletAdapter` — that wrapper is for our own
// sponsor service, and double-balancing would fail. And because somebody else is paying, their
// refusal is a real outcome the operator has to be able to read; see `attribute` in ./state.ts.
import type { DAppConnectorWallet } from '@stockandfoil/sdk';

/** Key the 1AM extension injects itself under. */
export const WALLET_KEY = '1am';

export interface OneAmConfiguration {
  networkId: string;
  indexerUri: string;
  indexerWsUri: string;
  proverServerUri?: string;
  substrateNodeUri: string;
}

export interface OneAmConnectedAPI extends DAppConnectorWallet {
  getConfiguration(): Promise<OneAmConfiguration>;
  getDustBalance(): Promise<{ cap: bigint | string; balance: bigint | string }>;
  getShieldedBalances(): Promise<Record<string, bigint | string>>;
  getUnshieldedBalances(): Promise<Record<string, bigint | string>>;
  getDustAddress(): Promise<{ dustAddress: string }>;
  /** Takes our `ZKConfigProvider` and returns a proving provider backed by ProofStation. */
  getProvingProvider(keyProvider: unknown): Promise<unknown>;
}

export interface OneAmInitialAPI {
  name?: string;
  apiVersion?: string;
  icon?: string;
  connect(networkId: string): Promise<OneAmConnectedAPI>;
}

/** Everything injected under `window.midnight`, whatever it calls itself. */
export const injectedWallets = (): Record<string, OneAmInitialAPI> =>
  (globalThis as { midnight?: Record<string, OneAmInitialAPI> }).midnight ?? {};

/**
 * Waits for the extension to inject itself — up to five seconds, as the guide's own snippet
 * does, because the content script does not always win the race with the page.
 */
export function detectWallet(timeoutMs = 5_000): Promise<OneAmInitialAPI | null> {
  return new Promise((resolve) => {
    const found = (): OneAmInitialAPI | undefined => injectedWallets()[WALLET_KEY];
    const immediate = found();
    if (immediate) {
      resolve(immediate);
      return;
    }
    const deadline = Date.now() + timeoutMs;
    const timer = setInterval(() => {
      const wallet = found();
      if (wallet) {
        clearInterval(timer);
        resolve(wallet);
      } else if (Date.now() > deadline) {
        clearInterval(timer);
        resolve(null);
      }
    }, 100);
  });
}

const asBigInt = (value: bigint | string | undefined): bigint => {
  if (value === undefined) return 0n;
  return typeof value === 'bigint' ? value : BigInt(value);
};

export interface WalletReading {
  shieldedAddress: string;
  shieldedCoinPublicKey: string;
  shieldedEncryptionPublicKey: string;
  unshieldedAddress: string;
  dustAddress?: string;
  dustBalanceSpeck: bigint;
  dustCapSpeck: bigint;
  shieldedBalances: Record<string, string>;
  unshieldedBalances: Record<string, string>;
}

/** Addresses and balances, each failure isolated so one missing method does not hide the rest. */
export async function readWallet(api: OneAmConnectedAPI): Promise<WalletReading> {
  const shielded = await api.getShieldedAddresses();
  const { unshieldedAddress } = await api.getUnshieldedAddress();
  const dustAddress = await api
    .getDustAddress()
    .then((r) => r.dustAddress)
    .catch(() => undefined);
  const dust = await api.getDustBalance().catch(() => ({ balance: 0n, cap: 0n }));
  const stringify = (balances: Record<string, bigint | string>): Record<string, string> =>
    Object.fromEntries(Object.entries(balances).map(([k, v]) => [k, v.toString()]));
  const shieldedBalances = await api.getShieldedBalances().then(stringify).catch(() => ({}));
  const unshieldedBalances = await api.getUnshieldedBalances().then(stringify).catch(() => ({}));

  return {
    shieldedAddress: shielded.shieldedAddress,
    shieldedCoinPublicKey: shielded.shieldedCoinPublicKey,
    shieldedEncryptionPublicKey: shielded.shieldedEncryptionPublicKey,
    unshieldedAddress,
    dustAddress,
    dustBalanceSpeck: asBigInt(dust.balance),
    dustCapSpeck: asBigInt(dust.cap),
    shieldedBalances,
    unshieldedBalances,
  };
}
